<div class="card"><div class="card-body"><h4>Marketing Consent</h4><form method="post" action="<?php echo site_url('email_marketing/consent/save'); ?>"><input type="hidden" name="<?php echo csrf_token(); ?>" value="<?php echo csrf_hash(); ?>"><input type="hidden" name="entity_type" value="<?php echo esc($type); ?>"><input type="hidden" name="entity_id" value="<?php echo (int)$id; ?>"><select name="consent" class="form-control"><option <?php echo $consent==='Unknown'?'selected':''; ?>>Unknown</option><option <?php echo $consent==='Opted In'?'selected':''; ?>>Opted In</option><option <?php echo $consent==='Opted Out'?'selected':''; ?>>Opted Out</option></select><button class="btn btn-primary mt15">Save consent</button></form></div></div>
